import Foundation

/// Fictional authenticated loader fixtures only; no real product/client material.
enum ReviewedScopeAliasTests {
    static func run(_ check: (String, Bool) -> Void) {
        do {
            let legacy = try ReviewedAnswerCatalog.decode(valid8)
            let docs = legacy.sources.map { KBDocument(name:$0.name, chunkCount:1, addedAt:.now, contentSHA256:$0.sha256) }
            let snapshot = legacy.admitted(documents:docs, folders:[], profileID:nil)
            check("scope aliases: signed eight-alias library remains usable",
                  snapshot.candidates(question:"How do I set fit sample?", referenceNames:[]).count == 1)
        } catch { check("scope aliases: legacy signed fixture error "+error.localizedDescription, false) }
        do {
            let catalog = try ReviewedAnswerCatalog.decode(valid16)
            let docs = catalog.sources.map { KBDocument(name:$0.name, chunkCount:1, addedAt:.now, contentSHA256:$0.sha256) }
            let snapshot = catalog.admitted(documents:docs, folders:[], profileID:nil)
            let spacing = catalog.answers[0], budget = catalog.answers[1]
            check("scope aliases: trusted sixteen-alias library admits both complete replies", snapshot.answers.count == 2 && snapshot.admissionIssues.isEmpty)
            // Each literal is a reviewed synonym in this fictional source. No
            // expected route is computed by the matching code under test.
            let phrases = ["fit sample", "fitted sample", "refit sample", "gap below sample",
                           "largest sample size", "maximum sample lines", "preserveSampleStyle", "sample in placement",
                           "sample gap", "sample spacing", "sample width", "sample line limit",
                           "sample preservation", "sample size", "sample height", "sample fitting"]
            for phrase in phrases {
                check("scope aliases: complete reply remains eligible for "+phrase,
                      snapshot.candidates(question:"How do I set "+phrase+"?", referenceNames:[]).map(\.id) == [spacing.id])
            }
            check("scope aliases: unrelated budget route remains eligible",
                  snapshot.candidates(question:"How do I open the sample budget?", referenceNames:[]).map(\.id) == [budget.id])
            let compound = "How do I open the sample budget and set the sample gap?"
            check("scope aliases: ninth alias keeps compound topics ambiguous", snapshot.questionRequirement(compound) == .ambiguous)
            check("scope aliases: compound cannot return a partial reply", snapshot.candidates(question:compound, referenceNames:[]).isEmpty)
            check("scope aliases: forced budget ID cannot answer the compound", !snapshot.permitsAnswer(for:budget.id, question:compound))
            check("scope aliases: forced spacing ID cannot answer the compound", !snapshot.permitsAnswer(for:spacing.id, question:compound))
            var off = docs[0]; off.scope = .off
            let missing = catalog.admitted(documents:[off,docs[1]], folders:[], profileID:nil)
            check("scope aliases: missing source leaves unrelated single-topic reply usable", missing.candidates(question:"How do I open the sample budget?", referenceNames:[]).map(\.id) == [budget.id])
            check("scope aliases: missing source cannot hide compound ninth-alias topic", missing.candidates(question:compound, referenceNames:[]).isEmpty && !missing.permitsAnswer(for:budget.id, question:compound))
            for question in ["How do I set sample gapper?", "How do I not set sample gap?",
                             "Is Sample Gap enabled?", "How do I set sample gap in version 9.9.9?",
                             "What does Sample Gap do and where is that option?",
                             "The note says \"How do I set sample gap?\". Is that true?"] {
                check("scope aliases: unrelated, unsupported, state or quoted question stays guarded: "+question,
                      snapshot.candidates(question:question, referenceNames:[]).isEmpty)
            }
        } catch { check("scope aliases: trusted sixteen-alias fixture error "+error.localizedDescription, false) }
        for (name,data) in invalid {
            do { _ = try ReviewedAnswerCatalog.decode(data); check("scope aliases: signed malformed "+name, false) }
            catch { check("scope aliases: signed malformed "+name, error.localizedDescription.contains("invalid reviewed question scope")) }
        }
        do {
            var object = try JSONSerialization.jsonObject(with:valid16) as! [String:Any]
            object["signature"] = Data(repeating:0,count:64).base64EncodedString()
            let tampered = try JSONSerialization.data(withJSONObject:object)
            do { _ = try ReviewedAnswerCatalog.decode(tampered); check("scope aliases: signature tampering remains rejected", false) }
            catch { check("scope aliases: signature tampering remains rejected", error.localizedDescription.contains("invalid trusted catalog signature")) }
        } catch { check("scope aliases: tamper fixture error", false) }
    }
}


// Signed fictional payloads; key material is never in this file.
extension ReviewedScopeAliasTests {
    static let valid8 = Data(base64Encoded: "")!
    static let valid16 = Data(base64Encoded: "")!
    static let invalid: [(String,Data)] = [
        ("invalid17", Data(base64Encoded: "")!),
        ("invalid-groups9", Data(base64Encoded: "")!),
        ("invalid-duplicate", Data(base64Encoded: "")!),
        ("invalid-words9", Data(base64Encoded: "")!),
        ("invalid-forbidden33", Data(base64Encoded: "")!),
        ("invalid-emptygroup", Data(base64Encoded: "")!),
    ]
}
